<div class="compact-grid"><section class="role-box" id="pending-approvals"><div style="display:flex;justify-content:space-between;align-items:center;gap:10px"><div><h3>Pending Approvals</h3>@if($role==='MAINTENANCE_ENGINEER')<small class="muted">Top 5 only. Full decision forms stay in My Technical Approvals.</small>@endif</div><div><span class="badge">Waiting: {{ $waitingApprovals }}</span> @if($breachedApprovals)<span class="badge red">Breached: {{ $breachedApprovals }}</span>@endif</div></div><div class="approval-list">@forelse($pendingApprovals as $approval)@php($sr=$approval->entity_type===\App\Models\ServiceRequest::class ? $serviceRequests->get($approval->entity_id) : null)<div class="approval-card"><div class="approval-head"><div><b>{{ str_replace('_',' ',$approval->action) }}</b><small>@if($sr){{ $sr->request_no }} · {{ $sr->subject }}@else{{ class_basename($approval->entity_type) }} #{{ $approval->entity_id }}@endif</small></div><span class="badge {{ $approval->due_at && $approval->due_at->isPast()?'red':'amber' }}">{{ $approval->due_at ? $approval->due_at->diffForHumans() : 'No deadline' }}</span></div>@if($sr)<div class="approval-meta"><span class="badge">{{ $sr->priority }}</span><span class="badge">{{ str_replace('_',' ',$sr->eligibility) }}</span><span class="badge">{{ $sr->company_name }}</span></div>@endif<div class="approval-cta"><small>Open full technical review and decision controls</small><a class="review-link" href="{{ route('workflow.approvals.index') }}">Review →</a></div></div>@empty<div class="empty-role">No approvals are waiting for this role right now.</div>@endforelse</div><div class="role-actions"><a class="btn" href="{{ route('workflow.approvals.index') }}">Open My Technical Approvals</a></div></section><section class="role-box"><h3>Recent Decisions</h3><div class="decisions">@forelse($recentDecisions as $decision)<div class="decision"><b>{{ str_replace('_',' ',$decision->action) }} · {{ $decision->status }}</b><small>{{ $decision->deci