@if($role==='MAINTENANCE_ENGINEER')<script>document.addEventListener('DOMContentLoaded',()=>{const cards=[...document.querySelectorAll('#technical-queue .queue-card')],filters=[...document.querySelectorAll('.queue-filter')],search=document.getElementById('queue-search');let current='all';const apply=()=>cards.forEach(c=>c.style.display=(current==='all'||c.dataset.filter===current)&&(!search.value||c.dataset.search.includes(search.value.toLowerCase()))?'block':'none');filters.forEach(b=>b.onclick=()=>{filters.forEach(x=>x.classList.remove('active'));b.classList.add('active');current=b.dataset.filter;apply()});document.querySelectorAll('[data-attention]').forEach(b=>b.onclick=()=>{const k=b.dataset.attention;if(['emergency','review','breached'].includes(k)){const f=filters.find(x=>x.dataset.filter===k);if(f)f.click();document.querySelector('.role-box')?.scrollIntoView({behavior:'smooth'})}else if(k==='workorder')document.getElementById('today-execution')?.scrollIntoView({behavior:'smooth'})});search.addEventListener('input',apply)});</script>@endif
